const normalize = value =>
  String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');

const email = normalize($json.email);

const phone = String($json.phone ?? '')
  .replace(/\D/g, '');

const submissionId = String($json.submission_id ?? '').trim();

// The same submission produces the same fingerprint,
// even if a webhook is delivered twice.
const fingerprintSource = JSON.stringify([
  normalize($json.client_id),
  email,
  phone,
  normalize($json.message),
  normalize($json.service),
  normalize($json.zip)
]);

return {
  json: {
    ...$json,
    normalizedEmail: email,
    normalizedPhone: phone,
    submission_id: submissionId || null,
    fingerprintSource,
    submitted_at: new Date().toISOString()
  }
};

const original = $('Prepare Lead Data').first().json;

// Preserve the safety result.
const safetyFlag =
  $('Safety Check').first().json.safety_flag === true;

// PostgreSQL must have granted the claim.
const claimGranted =
  $('Claim Lead Atomically').first().json.claim_outcome === 'claimed';

// Normalization helpers.
const normalizeEmail = value =>
  String(value || '').trim().toLowerCase();

const normalizePhone = value =>
  String(value || '').replace(/\D/g, '');

const normalizeMessage = value =>
  String(value || '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');

// Incoming lead.
const incomingEmail = normalizeEmail(
  original.normalizedEmail || original.email
);

const incomingPhone = normalizePhone(original.phone);

const incomingSubmissionId = String(
  original.submission_id || ''
).trim();

const incomingMessage = normalizeMessage(original.message);

const incomingTime = new Date(original.submitted_at).getTime();

const twelveHours = 12 * 60 * 60 * 1000;

// Existing leads from this client's Google Sheet.
const rows = $input.all();

let duplicate = false;
let possibleDuplicate = false;
let duplicateReason = '';
let matchedSubmissionId = null;

for (const item of rows) {
  const row = item.json;

  const rowSubmissionId = String(
    row.submission_id || ''
  ).trim();

  // 1. Identical submission ID.
  if (
    incomingSubmissionId &&
    rowSubmissionId &&
    incomingSubmissionId === rowSubmissionId
  ) {
    // Skip an old AI-failure row only when
    // PostgreSQL has granted recovery.
    const retryableAiFailure =
      String(row.reason || '').trim() ===
        'AI classification failed' &&
      claimGranted;

    if (retryableAiFailure) {
      continue;
    }

    duplicate = true;
    possibleDuplicate = false;
    duplicateReason = 'identical_submission_id';
    matchedSubmissionId = rowSubmissionId;
    break;
  }

  // 2. Check the 12-hour window.
  if (!row.submitted_at) {
    continue;
  }

  const rowTime = new Date(row.submitted_at).getTime();

  if (
    !Number.isFinite(incomingTime) ||
    !Number.isFinite(rowTime)
  ) {
    continue;
  }

  const timeDifference = incomingTime - rowTime;

  if (
    timeDifference < 0 ||
    timeDifference > twelveHours
  ) {
    continue;
  }

  const rowEmail = normalizeEmail(row.email);
  const rowPhone = normalizePhone(row.phone);

  // 3. Check whether this is the same customer.
  let sameCustomer = false;

  if (incomingEmail && incomingPhone) {
    sameCustomer =
      rowEmail === incomingEmail &&
      rowPhone === incomingPhone;
  } else if (incomingEmail) {
    sameCustomer = rowEmail === incomingEmail;
  } else if (incomingPhone) {
    sameCustomer = rowPhone === incomingPhone;
  }

  if (!sameCustomer) {
    continue;
  }

  // 4. Compare requests.
  const rowMessage = normalizeMessage(row.message);

  if (
    incomingMessage &&
    rowMessage &&
    incomingMessage === rowMessage
  ) {
    // A row left by a failed AI attempt is this same lead waiting
    // for its retry, not a duplicate. Without this, a lead that has
    // no submission_id could never be retried.
    if (
      String(row.reason || '').trim() ===
        'AI classification failed' &&
      claimGranted
    ) {
      continue;
    }

    duplicate = true;
    possibleDuplicate = false;
    duplicateReason = 'identical_request_within_12_hours';
    matchedSubmissionId = rowSubmissionId || null;
    break;
  }

  // Same customer, different request.
  possibleDuplicate = true;
  duplicateReason = 'same_customer_different_request';
  matchedSubmissionId = rowSubmissionId || null;
}

return [
  {
    json: {
      ...original,
      duplicate,
      possibleDuplicate,
      duplicateReason,
      matchedSubmissionId,
      safety_flag: safetyFlag
    }
  }
];

const result = $json.output?.[0]?.content?.[0]?.text;

if (!result || typeof result !== "object") {
  throw new Error("AI returned no valid classification object");
}

const validLeadTypes = ["hot", "warm", "cold"];

if (!validLeadTypes.includes(result.lead_type)) {
  throw new Error(
    `Invalid lead_type returned by AI: "${result.lead_type}". Expected hot, warm, or cold.`
  );
}

if (!result.service) {
  throw new Error("AI classification is missing service");
}

const validUrgencies = ["urgent", "soon", "non_urgent"];

if (!validUrgencies.includes(result.urgency)) {
  throw new Error("AI returned an invalid urgency");
}

if (typeof result.needs_human_review !== "boolean") {
  throw new Error("AI returned an invalid human-review flag");
}

// Retrieve the original lead after duplicate checking.
const original = $('Normalise Lead data').first().json;

const safetyFlag = original.safety_flag === true;

// Safety concerns must always receive human review.
const needsHumanReview =
  safetyFlag || result.needs_human_review;

// Safety concerns override ordinary lead classification.
const leadType = safetyFlag ? "hot" : result.lead_type;
const urgency = safetyFlag ? "urgent" : result.urgency;

const priorityMap = {
  hot: "high",
  warm: "normal",
  cold: "low"
};

const reviewReason = safetyFlag
  ? "Potential HVAC safety hazard. Immediate human review required."
  : result.review_reason || "";

return {
  json: {
    ...original,

    lead_type: leadType,
    service: result.service,
    urgency,
    reason: result.summary || "No summary provided",
    priority: priorityMap[leadType],

    safety_flag: safetyFlag,
    needs_human_review: needsHumanReview,
    review_reason: reviewReason
  }
};

const response = `Hi ${$json.name},

Thanks for reaching out about ${$json.service}. We’ve received your inquiry and will get back to you shortly.

Best regards,
${$('Client Config').item.json.business_name}`;

return {
  json: {
    ...$json,
    response: response
  }
};

