parameters.jsCode:
const websiteId = String($json.submission_id ?? '').trim();
const fingerprint = String($json.fingerprint_hash ?? '').trim();
const clientId = String($json.client_id ?? '').trim();

if (!clientId) {
  throw new Error('Missing client_id');
}

if (!websiteId && !fingerprint) {
  throw new Error('Missing submission ID and fingerprint');
}

const dedupKey = websiteId
  ? `website:${websiteId}`
  : `fingerprint:${fingerprint}`;

return {
  json: {
    ...$json,
    dedup_key: dedupKey,
    dedup_key_source: websiteId ? 'website' : 'fingerprint'
  }
};

const original = $('Select Dedup Key').first().json;

return {
  json: {
    ...original,
    atomic_claimed: true
  }
};

const original = $('Build Email Data').first().json;

return {
  json: {
    ...original,
    customer_email_status: $json.customer_email_status,
    customer_email_message_id: $json.customer_email_message_id
  }
};

const items = $input.all();

if (
  items.length !== 1 ||
  items[0].json.recording_result !== 'recorded'
) {
  throw new Error(
    'Customer email was sent, but database recording was not confirmed. Manual review required.'
  );
}

return items;

