const original = $('AI Error Handler').first().json;

return [{
  json: {
    ...original,
    recovery_marked: true
  }
}];

// AI classification failed, but the keyword Safety Check had already
// flagged this lead. Build the fields the safety branch needs so a
// possible gas / CO / fire report is never reduced to an "AI failed"
// notice.
const lead = $('Normalise Lead data').first().json;
const safety = $('Safety Check').first().json;

return [{
  json: {
    ...lead,
    lead_type: 'hot',
    urgency: 'urgent',
    priority: 'high',
    service: lead.service || 'Emergency HVAC safety review',
    reason:
      (safety.review_reason || 'Potential HVAC safety hazard.') +
      ' AI classification was unavailable.',
    needs_human_review: true,
    review_reason: safety.review_reason || '',
    ai_unavailable: true
  }
}];

